def k_colorable(G,k):
    colors={}
    def search():
        if len(colors)==len(G): return True
        v=max((v for v in G if v not in colors), key=lambda v:(len({colors[w] for w in G[v] if w in colors}),G.degree(v)))
        bad={colors[w] for w in G[v] if w in colors}
